import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.D3oaa6bG.js";const u=JSON.parse('{"title":"Properties","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/properties.md","filePath":"guide/usage/properties.md","lastUpdated":null}'),d={name:"guide/usage/properties.md"};function i(s,e,p,n,c,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h1><p>Properties are used to describe a <a href="./products.html">Product or Variant</a> in your store.</p><p>Properties serve two purposes:</p><ol><li>They can be used to describe a product. A user can filter on different properties and find matching products.</li><li>Different property values can be combined to define a <a href="./products.html">Variant</a>.</li></ol><h2 id="defining-properties" tabindex="-1">Defining properties <a class="header-anchor" href="#defining-properties" aria-label="Permalink to &quot;Defining properties&quot;">​</a></h2><p>Properties can be defined in the backend under <code>Catalogue &gt; Properties</code>.</p><h3 id="property-groups" tabindex="-1">Property groups <a class="header-anchor" href="#property-groups" aria-label="Permalink to &quot;Property groups&quot;">​</a></h3><p>Every property has to belong to a property group. Common property groups are <code>Size</code>, <code>Dimensions</code> or <code>Technical specs</code>. You can of course define as many groups as your use-case demands.</p><p>Every group needs to be given a <code>Name</code> (used in the backend). The <code>Display name</code> (optional name to use in the frontend) and <code>Description</code> attributes are optional.</p><p>If you manage a high number of products you can use the <code>Name</code> and <code>Display Name</code> properties to give your groups descriptive names with more context in the backend (<code>Bike Size</code>, <code>Shoe Size</code>, <code>Package Size</code>) while displaying a more generic name in the frontend (<code>Size</code> for everything, context is given by the currently viewed category).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make sure to name your groups only as specific as needed. Giving then generic names will make it easier to re-use them among different products.</p></div><h3 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to &quot;Properties&quot;">​</a></h3><p>Each <code>Property</code> belongs to one or multiple <code>Property Groups</code>.</p><p>A <code>Property</code> has a descriptive <code>Name</code>, a <code>Type</code> and an optional <code>Unit</code>.</p><p>The table below shows some common <code>Properties</code>.</p><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Unit</th><th>Options</th></tr></thead><tbody><tr><td>Size</td><td>Dropdown</td><td></td><td>S, M, L, XL</td></tr><tr><td>Color</td><td>Color</td><td></td><td></td></tr><tr><td>Width</td><td>Number</td><td>mm</td><td></td></tr><tr><td>Height</td><td>Number</td><td>mm</td><td></td></tr><tr><td>Material</td><td>Textarea</td><td></td><td></td></tr></tbody></table><h4 id="use-for-variants" tabindex="-1">Use for Variants <a class="header-anchor" href="#use-for-variants" aria-label="Permalink to &quot;Use for Variants&quot;">​</a></h4><p>If a <code>Property</code> will be used to describe the different <a href="./products.html">Variants of a Product</a> this option should be enabled. A perfect example is the <code>Size</code> property where a Product is available as differently sized Variants. The <code>Material</code> property will be the same for all sizes so it should <em>not</em> be used to describe Variants.</p><h4 id="filter-type" tabindex="-1">Filter type <a class="header-anchor" href="#filter-type" aria-label="Permalink to &quot;Filter type&quot;">​</a></h4><p>To make products filterable by a specific property, the <code>Filter type</code> option can be enabled.</p><p>The table below shows some common <code>Filter type</code> setups.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th></tr></thead><tbody><tr><td>Size</td><td>Set</td></tr><tr><td>Color</td><td>Set</td></tr><tr><td>Width</td><td>Range</td></tr><tr><td>Height</td><td>Range</td></tr><tr><td>Ingredients</td><td>Without filter</td></tr></tbody></table><p>A <code>Set</code> filter will display all available Property values. The user can select one or many of these values to filter products.</p><p>A <code>Range</code> filter will display a slider control. The user can set a specific range to filter matching products.</p>',24)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
